202	    /**
203	     * Normalize an owner address: trim, collapse each run of whitespace to a single
204	     * space, upper-case, and expand common street-type abbreviations
205	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
206	     * A {@code null} value normalizes to the empty string.
207	     */
208	    private static String normalizeAddress(String value) {
209	        if (value == null) {
210	            return "";
211	        }
212	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
213	        if (collapsed.isEmpty()) {
214	            return "";
215	        }
216	        String[] tokens = collapsed.split(" ");
217	        StringBuilder sb = new StringBuilder(collapsed.length());
218	        for (int i = 0; i < tokens.length; i++) {
219	            if (i > 0) {
220	                sb.append(' ');
221	            }
222	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
223	        }
224	        return sb.toString();
225	    }
