228	     * Normalize an owner household field (last name or address) for duplicate detection:
229	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
230	     * A {@code null} value normalizes to the empty string.
231	     */
232	    private static String normalizeHouseholdKey(String value) {
