239	    /**
240	     * Normalize a telephone number to E.164 form.
241	     *
242	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
243	     * explicit leading {@code '+'} and country code it is kept; otherwise the
244	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
245	     * dropped from the national digits. The result must contain 8 to 15 digits
246	     * after the {@code '+'}.
247	     *
248	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
249	     *         the input is absent or cannot form a valid E.164 number.
250	     */
251	    private static String toE164(String raw) {
252	        if (raw == null) {
253	            return null;
254	        }
255	        String trimmed = raw.trim();
256	        boolean hasCountryCode = trimmed.startsWith("+");
257	        // Strip spaces, dashes and brackets.
258	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
259	        String digits;
260	        if (hasCountryCode) {
261	            // Keep the explicit country code; drop the leading '+' for validation.
262	            digits = stripped.substring(1);
263	        } else {
264	            // No country code: assume '+61' and drop a single leading '0'.
265	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
266	            digits = "61" + national;
267	        }
268	        if (!digits.matches("\\d{8,15}")) {
269	            return null;
270	        }
271	        return "+" + digits;
272	    }
