274	    /**
275	     * Build the next customer code, formatted {@code '<LAST3>-<NNNN>'}.
276	     *
277	     * <p>{@code LAST3} is the upper-cased first three letters of {@code lastName}
278	     * (fewer if the name is shorter), and {@code NNNN} is a global 4-digit
279	     * zero-padded sequence equal to one more than the current number of owners
280	     * (e.g. {@code 'SMI-0007'}).
281	     */
282	    /**
283	     * Count the existing owners whose first and last name match the given names,
284	     * compared case-insensitively. Used to record an owner's namesake count at the
285	     * moment before it is created.
286	     */
287	    private int countNamesakes(String firstName, String lastName) {
288	        return (int) this.clinicService.findAllOwners().stream()
289	            .filter(existing -> existing.getFirstName() != null
290	                && existing.getFirstName().equalsIgnoreCase(firstName)
291	                && existing.getLastName() != null
292	                && existing.getLastName().equalsIgnoreCase(lastName))
293	            .count();
294	    }
295	
296	    private String nextCustomerCode(String lastName) {
297	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
298	        int sequence = this.clinicService.findAllOwners().size() + 1;
299	        return String.format("%s-%04d", last3, sequence);
300	    }
